      "qualname": "src/cachetools/__init__.py::cachedmethod",
      "source": "def cachedmethod(cache, key=keys.methodkey, lock=None, condition=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """

    def decorator(method):
        clear_method = None
        wrapper_func = None

        if condition is not None:
            # Condition-based synchronization for stampede protection
            def wrapper(self, *args, **kwargs):
                current_cache = cache(self)
                if current_cache is None:
                    return method(self, *args, **kwargs)
                current_key = key(self, *args, **kwargs)
                cond_obj = condition(self) if callable(condition) else condition
                with cond_obj:
                    try:
                        return current_cache[current_key]
                    except KeyError:
                        pass
                    if not hasattr(current_cache, '_in_progress'):
                        current_cache._in_progress = set()
                    if current_key in current_cache._in_progress:
                        cond_obj.wait()
                        try:
                            return current_cache[current_key]
                        except KeyError:
                            pass
                    current_cache._in_progress.add(current_key)
                result_value = method(self, *args, **kwargs)
                with cond_obj:
                    try:
                        current_cache[current_key] = result_value
                    except ValueError:
                        current_cache._in_progress.discard(current_key)
                        cond_obj.notify_all()
                        return result_value
                    current_cache._in_progress.discard(current_key)
                    cond_obj.notify_all()
                    return result_value

            def clear(self):
                current_cache = cache(self)
                if current_cache is not None:
                    cond_obj = condition(self) if callable(condition) else condition
                    with cond_obj:
                        current_cache.clear()
                        if hasattr(current_cache, '_in_progress'):
                            current_cache._in_progress.clear()

            wrapper_func = wrapper
            clear_method = clear

        elif lock is None:

            def wrapper(self, *args, **kwargs):
                current_cache = cache(self)
                if current_cache is None:
                    return method(self, *args, **kwargs)
                current_key = key(self, *args, **kwargs)
                try:
                    return current_cache[current_key]
                except KeyError:
                    pass  # key not found
                result_value = method(self, *args, **kwargs)
                try:
                    current_cache[current_key] = result_value
                except ValueError:
                    pass  # value too large
                return result_value

            def clear(self):
                current_cache = cache(self)
                if current_cache is not None:
                    current_cache.clear()

            wrapper_func = wrapper
            clear_method = clear

        else:

            def wrapper(self, *args, **kwargs):
                current_cache = cache(self)
                if current_cache is None:
                    return method(self, *args, **kwargs)
                current_key = key(self, *args, **kwargs)
                try:
                    with lock(self):
                        return current_cache[current_key]
                except KeyError:
                    pass  # key not found
                result_value = method(self, *args, **kwargs)
                # in case of a race, prefer the item already in the cache
                try:
                    with lock(self):
                        return current_cache.setdefault(current_key, result_value)
                except ValueError:
                    return result_value  # value too large

            def clear(self):
                current_cache = cache(self)
                if current_cache is not None:
                    with lock(self):
                        current_cache.clear()

            wrapper_func = wrapper
            clear_method = clear

        wrapper_func.cache = cache
        wrapper_func.cache_key = key
        wrapper_func.cache_lock = lock
        wrapper_func.cache_clear = clear_method

        return functools.update_wrapper(wrapper_func, method)

    return decorator"
