      "qualname": "src/cachetools/_decorators.py::_cached_condition_info",
      "source": "def _cached_condition_info(func, cache, key, cond, info):
    """Wrapper using threading.Condition for stampede protection."""
    hit_count = 0
    miss_count = 0
    # Track keys currently being computed (separate from cache data)
    in_progress_keys = set()

    def wrapper(*args, **kwargs):
        nonlocal hit_count, miss_count
        lookup_key = key(*args, **kwargs)
        with cond:
            # First check if already cached
            try:
                cached_val = cache[lookup_key]
                hit_count += 1
                return cached_val
            except KeyError:
                pass
            # Cache miss - check if someone else is computing it
            if lookup_key in in_progress_keys:
                # Someone else is computing, wait for notification
                cond.wait()
                # After waking, check again
                try:
                    cached_val = cache[lookup_key]
                    hit_count += 1
                    return cached_val
                except KeyError:
                    pass
            # We are the first to discover this miss
            miss_count += 1
            in_progress_keys.add(lookup_key)
        # Compute outside the lock
        computed_val = func(*args, **kwargs)
        with cond:
            try:
                cache[lookup_key] = computed_val
            except ValueError:
                # value too large
                in_progress_keys.discard(lookup_key)
                cond.notify_all()
                return computed_val
            in_progress_keys.discard(lookup_key)
            cond.notify_all()
            return computed_val

    def cache_clear():
        nonlocal hit_count, miss_count
        with cond:
            cache.clear()
            in_progress_keys.clear()
            hit_count = 0
            miss_count = 0

    def cache_info():
        with cond:
            return info(hit_count, miss_count)

    wrapper.cache_clear = cache_clear
    wrapper.cache_info = cache_info
    return wrapper"
