      "qualname": "src/cachetools/_decorators.py::_cached_wrapper",
      "source": "def _cached_wrapper(func, cache, key, lock=None, info=None, condition=None):
    final_wrapper = None
    if condition is not None:
        if info is not None:
            final_wrapper = _cached_condition_info(func, cache, key, condition, info)
        else:
            final_wrapper = _cached_condition(func, cache, key, condition)
            final_wrapper.cache_info = None
    elif info is not None:
        if cache is None:
            final_wrapper = _uncached_info(func, info)
        elif lock is None:
            final_wrapper = _cached_unlocked_info(func, cache, key, info)
        else:
            final_wrapper = _cached_locked_info(func, cache, key, lock, info)
    else:
        if cache is None:
            final_wrapper = _uncached(func)
        elif lock is None:
            final_wrapper = _cached_unlocked(func, cache, key)
        else:
            final_wrapper = _cached_locked(func, cache, key, lock)
        final_wrapper.cache_info = None
    return final_wrapper"
