      "qualname": "src/cachetools/func.py::_cache",
      "source": "def _cache(cache, maxsize, typed):
    def decorator(func):
        selected_key_func = keys.typedkey if typed else keys.hashkey
        wrapped_func = cached(cache=cache, key=selected_key_func, condition=threading.Condition(), info=True)(func)
        wrapped_func.cache_parameters = lambda: {"maxsize": maxsize, "typed": typed}
        return wrapped_func

    return decorator"
